sys_script_include.script:
var ReferenceSync = Class.create();

// Per table: legacy LOB choice column, product reference that drives the line,
// legacy territory column, and the wildcard value that means "any line".
ReferenceSync.CONFIG = {
    submission: { lob: 'line_of_business' },
    submission_line: { lob: 'line_of_business', product: 'product', territory: 'territory' },
    product: { lob: 'line_of_business' },
    policy: { lob: 'line_of_business', product: 'product', territory: 'territory' },
    quote_option: { lob: 'line_of_business', product: 'product' },
    quote_option_line: { product: 'product' },
    policy_version: { product: 'product' },
    existing_policy: { lob: 'line_of_business' },
    exposure_item: { lob: 'line_of_business' },
    extraction_mapping: { lob: 'line_of_business', wildcard: 'all' },
    module_plan: { lob: 'line_of_business', wildcard: 'all' },
    rate_table: { lob: 'line_of_business' },
    rate_factor: { lob: 'line_of_business' },
    renewal_case: { lob: 'line_of_business' },
    loa_authority_limit: { lob: 'line_of_business', wildcard: 'all' },
    loa_authority_grant: { lob: 'line_of_business', wildcard: 'all' },
    loa_evaluation: { lob: 'line_of_business' },
    loa_metric: { lob: 'line_of_business', wildcard: 'all' },
    uw_rule_group_definition: { lob: 'lob' }
};
ReferenceSync.LOB_SCHEME = 'legacy_lob';
ReferenceSync.TERRITORY_SCHEME = 'legacy_territory';
ReferenceSync.INTEGRATION_ROLE = 'x_gegis_ins_policy.integration_user';

ReferenceSync.prototype = {

    initialize: function () {
        this.values = new ValueMapper();
    },

    // Called from the before insert/update business rules.
    apply: function (current) {
        var short = current.getTableName().replace(Constants.SCOPE + '_', '');
        var cfg = ReferenceSync.CONFIG[short];
        if (!cfg)
            return;
        // 1. the product decides the business line (a product is filed for one line)
        if (cfg.product && current.getValue(cfg.product) && (current[cfg.product].changes() || current.business_line.nil())) {
            var fromProduct = this._productLine(current.getValue(cfg.product));
            if (fromProduct)
                current.setValue('business_line', fromProduct);
        }
        // 2. master <-> legacy choice
        if (cfg.lob)
            this._syncPair(current, 'business_line', cfg.lob, ReferenceSync.LOB_SCHEME, Constants.TABLE.LINE_OF_BUSINESS, cfg.wildcard);
        // 3. jurisdiction <-> legacy territory
        if (cfg.territory)
            this._syncPair(current, 'jurisdiction', cfg.territory, ReferenceSync.TERRITORY_SCHEME, Constants.TABLE.JURISDICTION, '');
    },

    // External-PAS projections are read-only for people; integrations and system jobs may write.
    guardProjection: function (current) {
        if (current.getValue('system_of_record') !== Constants.CHOICE.SYSTEM_OF_RECORD.EXTERNAL)
            return;
        if (current.system_of_record.changes())
            return;   // switching the system of record itself is allowed
        if (!gs.isInteractive() || gs.hasRole(ReferenceSync.INTEGRATION_ROLE))
            return;
        current.setAbortAction(true);
        gs.addErrorMessage(gs.getMessage('This record is a read-only projection of the external policy administration system. Change it there; the next sync updates Policy Suite.'));
    },

    // master = reference to a table with a code column; legacy = choice holding the old token.
    _syncPair: function (current, masterField, legacyField, scheme, masterTable, wildcard) {
        if (!current.isValidField(masterField) || !current.isValidField(legacyField))
            return;
        var masterChanged = current[masterField].changes() && !current[masterField].nil();
        var legacyValue = String(current.getValue(legacyField) || '');
        if (masterChanged) {
            var legacy = this._legacyFor(current, legacyField, scheme, this._code(masterTable, current.getValue(masterField)));
            if (legacy && legacy !== legacyValue)
                current.setValue(legacyField, legacy);
            return;
        }
        if (!legacyValue || legacyValue === wildcard)
            return;
        if (current[legacyField].changes() || current[masterField].nil()) {
            var code = this.values.map(scheme, legacyValue, false, false);
            var masterId = code ? this._byCode(masterTable, code) : '';
            if (masterId)
                current.setValue(masterField, masterId);
        }
    },

    // Pick the legacy token for a master code that is actually a choice on this column.
    _legacyFor: function (current, legacyField, scheme, code) {
        if (!code)
            return '';
        var candidates = this.values.sources(scheme, code);
        var allowed = current[legacyField].getChoices ? current[legacyField].getChoices() : null;
        var list = [];
        if (allowed) {
            for (var i = 0; i < allowed.length; i++)
                list.push(String(allowed[i]));
        }
        if (list.indexOf(code) > -1 || (!list.length && candidates.indexOf(code) > -1))
            return code;
        for (var j = 0; j < candidates.length; j++) {
            if (!list.length || list.indexOf(candidates[j]) > -1)
                return candidates[j];
        }
        return '';
    },

    _productLine: function (productId) {
        var p = new GlideRecord(Constants.TABLE.PRODUCT);
        return p.get(productId) ? String(p.getValue('business_line') || '') : '';
    },

    _code: function (table, id) {
        var gr = new GlideRecord(table);
        return id && gr.get(id) ? String(gr.getValue('code') || '') : '';
    },

    _byCode: function (table, code) {
        var gr = new GlideRecord(table);
        gr.addQuery('code', code);
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr.getUniqueValue() : '';
    },

    type: 'ReferenceSync'
};
